import{d as c,C as t,o as u,c as b,j as a,a as s,E as r,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第七十四章","description":"辨民不畏死与若使的假设，依诡异乱群之注读为奇，并以代大匠斫理解擅代杀罚之戒。","frontmatter":{"title":"道德经第七十四章","description":"辨民不畏死与若使的假设，依诡异乱群之注读为奇，并以代大匠斫理解擅代杀罚之戒。","category":"guide","aliases":["道德经第七十四章","老子第七十四章","dao de jing chapter 74"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-74.md","filePath":"daoism/dao-de-jing/chapter-74.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-74.md"},y=c({...g,setup(m){const i=[{id:"when-death-no-longer-deterrs",label:"民不畏死，奈何以死惧之",showLabel:!0,sentences:[["民不畏死，奈何以死",{text:"惧",glossary:"ju"},"之？"]],note:["【白话】百姓若已经不怕死，又怎么能再用死来使他们害怕呢？开头反问，以不畏死的处境检验威吓手段是否仍然有效。","【读法】惧在这里有使动意味，是使人恐惧。可与第七十二章民不畏威、第七十五章民之轻死相参，追问人为什么走到不畏死，而不只问惩罚够不够重。"]},{id:"the-hypothetical-case",label:"若使民常畏死",showLabel:!0,sentences:[["若使民常畏死，而为",{text:"奇",glossary:"qi"},"者吾得",{text:"执",glossary:"zhi-grasp"},"而杀之，孰敢？"]],note:["【白话】假如能使百姓始终畏惧死亡，而对扰乱群体秩序的人，我能将他捕执并杀死，那么谁还敢如此呢？这是由若使开启的假设。","【王弼注择要】「诡异乱群，谓之奇也。」注限定为奇所指，不是说一切与众不同的个性、见解都属于应受刑杀的奇。","【读法】本句保留古代以刑杀论治的表达。读完整章，还要看其后常有司杀者与代杀反伤，不能抽出这一假设当作本章最终的治理命令。"]},{id:"killing-has-its-charge",label:"常有司杀者杀",showLabel:!0,sentences:[["常有",{text:"司杀",glossary:"sisha"},"者杀。"]],note:["【白话】自有掌管杀罚者执行杀罚。司是主管，司杀者先按有其所司来理解，这一句把前面的吾得杀之转向杀有所归属。","【王弼注择要】所据末注说「不仁者，人之所疾也，故曰常有司杀也」，以不仁为人所憎恶来说明其所归。","【读法】经文没有在此直接列出一个现代官职。可与上章天道、天网参读，但所引王注并未在这句话里直说司杀者就是某个具名神祇，本页不据此补造定义。"]},{id:"substituting-for-the-master",label:"夫代司杀者杀",showLabel:!0,sentences:[["夫代",{text:"司杀",glossary:"sisha"},"者杀，是谓代",{text:"大匠",glossary:"dajiang"},{text:"斫",glossary:"zhuo"},"。"]],note:["【白话】代替掌管杀罚者去执行杀罚，就好比代替技艺精熟的大工匠砍削木料。经文用这一个比喻，指出擅代其事的危险。","【读法】本站保留这句完整经文；所据经注连排录文此处作夫司杀者是大匠斲，字面不同，不能拿它当作本站整句逐字一致的来源。","【读法】比喻仍服务于代司杀者杀，不只是一条让专业的人做专业的事的泛泛劝告；也不能由此给任何人自封掌握生杀的资格。"]},{id:"the-injury-of-usurping-the-task",label:"夫代大匠斫者",showLabel:!0,sentences:[["夫代",{text:"大匠",glossary:"dajiang"},{text:"斫",glossary:"zhuo"},"者，",{text:"希",glossary:"xi"},"有不伤其手矣。"]],note:["【白话】代替大工匠砍削木料的人，很少有不伤到自己手的。结尾以手伤的切近形象，收束代行杀罚可能反伤自身的警戒。","【读法】希为稀少，斫为砍削；本站斫对应所据录文斲。所据本句后没有另见解释伤手的独立王注，不将本站延伸判断作古注引用。","【读法】与开头相照，威吓失效不必然能靠加大杀罚补救；本章把问题转到是否可以擅代其所司，以及代行者自身承受的后果。"]}],o=[{id:"ju",term:"惧",sense:1},{id:"qi",term:"奇",sense:2},{id:"zhi-grasp",term:"执",sense:3},{id:"sisha",term:"司杀",sense:1},{id:"dajiang",term:"大匠",sense:1},{id:"zhuo",term:"斫",sense:1},{id:"xi",term:"希",sense:2}];return(x,e)=>{const n=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十四章",tabindex:"-1"},[s("道德经第七十四章 "),a("a",{class:"header-anchor",href:"#道德经第七十四章","aria-label":'Permalink to "道德经第七十四章"'},"​")],-1)),r(n,{title:"用死威吓失效之后，为什么转到代大匠斫",summary:"本章先问：民若已不畏死，用死威吓还有何用？接着提出若使民常畏死的假设，再转到杀有所司与代大匠斫的反伤。阅读时要保留这几次转折，不把全章缩成更严惩罚，或只剩一般的专业分工格言。",points:[{label:"先读",text:"开头是对现实威吓失效的反问；若使另起假设，不把两层语气混在一起。"},{label:"再辨",text:"为奇依王注诡异乱群读，司杀先保留掌杀罚之任，不直接套现代官职。"},{label:"后看",text:"代司杀与代大匠相喻，结尾伤手写擅代之后反伤自身。"}],hint:"惧读 jù，在以死惧之中有使人害怕之意；奇读 qí，斫读 zhuó，希取稀少义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:i,glossary:o}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"民不畏死，奈何以死惧之？",tone:"从威吓的条件反问",guide:"先看人已不畏死的处境，再读刑杀手段为何失去作用。"},{text:"常有司杀者杀。",tone:"从吾杀转到有所司",guide:"此句开启下文代杀之戒，不宜跳过。"},{text:"夫代大匠斫者，希有不伤其手矣。",tone:"比喻的落点是反伤",guide:"手伤不是另起工艺话题，仍在解释代司杀者杀的风险。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:o}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-若使民常畏死-与开头是什么关系" tabindex="-1">象：若使民常畏死，与开头是什么关系？ <a class="header-anchor" href="#象-若使民常畏死-与开头是什么关系" aria-label="Permalink to &quot;象：若使民常畏死，与开头是什么关系？&quot;">​</a></h3><p>开头指出民不畏死时，死刑威吓难以成立；若使则提出另一种条件下的假设。读者须保留这种语气变化，再看下文对代杀的警戒，不能只摘其中一层当作全章主张。</p><h3 id="理-司杀者可以直接译成刽子手或某个现代机关吗" tabindex="-1">理：司杀者可以直接译成刽子手或某个现代机关吗？ <a class="header-anchor" href="#理-司杀者可以直接译成刽子手或某个现代机关吗" aria-label="Permalink to &quot;理：司杀者可以直接译成刽子手或某个现代机关吗？&quot;">​</a></h3><p>这样会过早收窄所指。经文重在杀有所司，所据王注又由不仁者为人所疾说明其归属；它没有在所引文字中列出现代制度的职名，应先保留古代论述本身的层次。</p><h3 id="用-今天怎样借用代大匠斫-而不抽空刑杀语境" tabindex="-1">用：今天怎样借用代大匠斫，而不抽空刑杀语境？ <a class="header-anchor" href="#用-今天怎样借用代大匠斫-而不抽空刑杀语境" aria-label="Permalink to &quot;用：今天怎样借用代大匠斫，而不抽空刑杀语境？&quot;">​</a></h3><p>先承认它原本谈的是生杀及其后果，再在现代事务中反省权责、判断依据和不可挽回的代价。程序与分工可以成为相参点，但不是把古文直接改说成一套现代制度。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>先问威吓为何已经失效。</strong> 如果一个人已经不再在乎惩罚，继续提高威吓未必能改变处境。需要了解其承受的压力、诉求和规则失效的原因，再决定如何回应。</p><p><strong>承担处置，也要接受约束。</strong> 涉及他人重大利益时，明确谁有职责、依据是什么、如何复核。代匠伤手的启发，可以落在防止一时愤怒或个人确信越过应有的核实。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否在回应别人不再配合时，只想到更重的后果？面对难以挽回的处置，我有没有弄清自己的职责、依据和复核路径？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文、标点与别名沿本站保留，据卷四 009a–009b 电子录文核对；若使、常有司杀者依语义拆开，不改字序。</li><li>本站夫代司杀者杀，是谓代大匠斫，所据经注连排此处作夫司杀者是大匠斲；保留并列说明，不据后者静默删改本站经文，也不把后者当本站整句的逐字证明。</li><li>本站斫对应所据斲；希复用稀少义，奇按诡异乱群谓之奇也新增义项，执按捕执义分开，不沿执大象的持守义。</li><li>所据篇末注另有为逆顺者之所恶忿也等连文，本页不擅补字句读而作定解；只节引不仁者人之所疾也故曰常有司杀也等可明确对应语句。</li><li>古代刑杀、天道的讨论与现代权责、核实的启发分层；古注节引转简体并加标点，尚未逐字核对影印。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_004.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷四 HFL 本电子录文，009a–009b</a>。</p>',15))])}}});export{_ as __pageData,y as default};
